const evidence=[{kind:'Primary record',text:'Payment voucher shows KSh 38.4M paid to Medisource Example Ltd.',state:'Documented'},{kind:'Field check',text:'Two sampled clinics could not locate the listed equipment serial numbers.',state:'Investigative finding'},{kind:'Missing record',text:'Inspection and acceptance certificate not present in the obtained procurement file.',state:'Unresolved'},{kind:'Company record',text:'Supplier was incorporated 73 days before the award.',state:'Context only'}];const el=document.getElementById('evidence');evidence.forEach(x=>{const d=document.createElement('div');d.className='evidence';d.innerHTML=`<div class="kind">${x.kind}</div><div>${x.text}</div><div class="state">${x.state}</div>`;el.appendChild(d)});const doctrine='FRAME UNIVERSE BLIND-SPOT VIEWPOINT PROVENANCE RIVALS CAUSALITY INVERSION TRANSFER STOP'.split(' ');const dd=document.getElementById('doctrine');doctrine.forEach(x=>{const s=document.createElement('span');s.textContent=x;dd.appendChild(s)});document.getElementById('searchBtn').addEventListener('click',()=>{const q=document.getElementById('q').value.toLowerCase();const m=document.getElementById('searchMsg');m.textContent=(q.includes('clinic')||q.includes('kijani')||q.includes('medisource'))?'1 synthetic demonstration case found below.':'No prototype record found. Production search will span entities, cases, contracts, assets and evidence.'});